const sampleProperties=[
 {id:'house-model-town',title:'3 BHK Independent House',type:'House',location:'Model Town, Ludhiana',price:8500000,area:'150 Sq. Yards',beds:3,baths:3,status:'Available',image:'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=85',description:'A bright independent home in a peaceful residential pocket, with a modern kitchen, covered parking and a sunny terrace.'},
 {id:'plot-south-city',title:'Premium Corner Plot',type:'Plot',location:'South City, Ludhiana',price:4200000,area:'250 Sq. Yards',beds:0,baths:0,status:'Available',image:'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1200&q=85',description:'A well-positioned corner plot near the main road. Ideal for a family home or long-term investment.'},
 {id:'flat-sarabha-nagar',title:'2 BHK Garden Apartment',type:'Flat',location:'Sarabha Nagar, Ludhiana',price:6150000,area:'1,280 Sq. Ft.',beds:2,baths:2,status:'On hold',image:'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=1200&q=85',description:'Move-in ready apartment with garden views, lift access, security and a dedicated car space.'},
 {id:'shop-legacy',title:'High-Street Commercial Shop',type:'Shop',location:'Ferozepur Road, Ludhiana',price:7200000,area:'410 Sq. Ft.',beds:0,baths:1,status:'Sold',image:'https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=1200&q=85',description:'High-visibility commercial unit on a busy retail stretch with excellent frontage.'}
];
const storageKey='propertydesk-properties'; let properties=JSON.parse(localStorage.getItem(storageKey)||'null')||sampleProperties;
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function save(){localStorage.setItem(storageKey,JSON.stringify(properties))}function visible(){const q=search.value.toLowerCase();return properties.filter(p=>(!q||`${p.title} ${p.location}`.toLowerCase().includes(q))&&(!typeFilter.value||p.type===typeFilter.value)&&(!statusFilter.value||p.status===statusFilter.value))}
const grid=document.querySelector('#property-grid'),stats=document.querySelector('#stats'),search=document.querySelector('#search'),typeFilter=document.querySelector('#type-filter'),statusFilter=document.querySelector('#status-filter');
function render(){const list=visible();document.querySelector('#result-count').textContent=`${list.length} ${list.length===1?'property':'properties'} found`;const available=properties.filter(p=>p.status==='Available').length;stats.innerHTML=`<div class="stat"><b class="stat-num">${properties.length}</b><span class="stat-label">Total properties</span></div><div class="stat"><b class="stat-num">${available}</b><span class="stat-label">Available now</span></div><div class="stat"><b class="stat-num">${properties.filter(p=>p.status==='Sold').length}</b><span class="stat-label">Sold properties</span></div>`;grid.innerHTML=list.length?list.map(p=>`<article class="card" data-id="${p.id}"><div class="card-image" style="background-image:url('${esc(p.image)}')"><span class="pill ${p.status==='Sold'?'sold':p.status==='On hold'?'hold':''}">${esc(p.status)}</span></div><div class="card-body"><h3>${esc(p.title)}</h3><p class="location">⌖ ${esc(p.location)}</p><div class="price">${money(p.price)}</div><div class="details">${esc(p.area)}${+p.beds?` · ${p.beds} bed`:''}${+p.baths?` · ${p.baths} bath`:''}</div></div></article>`).join(''):`<div class="empty">No properties match these filters.</div>`;document.querySelectorAll('.card').forEach(c=>c.onclick=()=>openProperty(c.dataset.id))}
function openProperty(id){const p=properties.find(x=>x.id===id);if(!p)return;const msg=`🏠 Property: ${p.title}\n📍 Location: ${p.location}\n💰 Price: ${money(p.price)}\n📐 Area: ${p.area}${p.beds?`\n🛏️ Bedrooms: ${p.beds}`:''}${p.baths?`\n🛁 Bathrooms: ${p.baths}`:''}\n\nInterested? Reply for more details.`;document.querySelector('#modal-content').innerHTML=`<div class="modal-hero" style="background-image:url('${esc(p.image)}')"></div><p class="eyebrow">${esc(p.type)} · ${esc(p.status)}</p><h2>${esc(p.title)}</h2><p class="location">⌖ ${esc(p.location)}</p><div class="modal-price">${money(p.price)}</div><div class="details">${esc(p.area)}${p.beds?` · ${p.beds} bedrooms`:''}${p.baths?` · ${p.baths} bathrooms`:''}</div><p class="modal-desc">${esc(p.description||'No description added yet.')}</p><div class="share-box"><b>Share on WhatsApp</b><div class="share-row"><input id="phone" inputmode="numeric" placeholder="Customer WhatsApp number (10 digits)"/><button class="whatsapp" id="share-btn">Share</button></div></div>`;const d=document.querySelector('#property-dialog');d.showModal();document.querySelector('#share-btn').onclick=()=>{const n=document.querySelector('#phone').value.replace(/\D/g,'');if(!/^[6-9]\d{9}$/.test(n)){alert('Please enter a valid 10-digit Indian mobile number.');return}window.open(`https://wa.me/91${n}?text=${encodeURIComponent(msg)}`,'_blank')}}
document.querySelectorAll('.add-trigger').forEach(b=>b.onclick=()=>document.querySelector('#add-dialog').showModal());document.querySelector('[data-close]').onclick=()=>document.querySelector('#add-dialog').close();document.querySelector('#property-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const p={...f,id:`property-${Date.now()}`,price:Number(f.price),beds:Number(f.beds),baths:Number(f.baths),image:f.image||'https://images.unsplash.com/photo-1564013799919-ab600027ffc6?auto=format&fit=crop&w=1200&q=85'};properties.unshift(p);save();render();e.target.reset();document.querySelector('#add-dialog').close()};[search,typeFilter,statusFilter].forEach(x=>x.addEventListener('input',render));document.querySelector('#clear-filters').onclick=()=>{search.value='';typeFilter.value='';statusFilter.value='';render()};render();if(location.hash.startsWith('#property='))openProperty(location.hash.split('=')[1]);
